SCENE w=480 h=480 fit=contain
# widget header hdr1 {"x":24,"y":0,"w":432,"h":64,"title":"Power","clock":false,"counts":true,"keys":{}}
G id=hdr1 {
    R x=24.5 y=0.5 w=431 h=63 f=#1A1A1A s=#4A4A4A sw=1
    G v==gt($hdr1_crit,0) {
        C cx=380 cy=32 rx=8 ry=8 f=#EF5350
        T x=398 y=15 w=40 h=34 text="{$hdr1_crit:%.0f}" size=24 f=#F2F2F2 align=right valign=middle
    }
    G v==gt($hdr1_warn,0) {
        C cx=298 cy=32 rx=8 ry=8 f=#F0B429
        T x=316 y=15 w=40 h=34 text="{$hdr1_warn:%.0f}" size=24 f=#F2F2F2 align=right valign=middle
    }
    T x=42 y=4 w=222 h=56 text=Power size=30 weight=bold f=#F2F2F2 valign=middle fit=ellipsis
}
# widget bar bar1 {"x":24,"y":90,"w":432,"h":30,"orient":"h","stateMode":"bound","marks":[],"target":false,"floor":0,"critBelow":0.1,"warnBelow":0.25,"cells":0,"keys":{}}
G id=bar1 {
    R x=24 y=90 w=432 h=30 rx=3 f=#121212
    R x=28 y=94 w==clamp($bar1_lvl,0,1)*424 h=22 rx=2 f==if(eq($bar1_st,1),#4CC38A,if(eq($bar1_st,2),#F0B429,if(eq($bar1_st,3),#EF5350,#9A9A9A)))
}
# widget options og1 {"x":24,"y":140,"w":432,"h":54,"options":[{"label":"Auto","value":0,"key":0},{"label":"On","value":1,"key":1},{"label":"Off","value":2,"key":2}],"gap":10,"keys":{}}
G id=og1 {
    G id=og1_g0 {
        R id=og1_o0 click=1 x=24 y=140 w=137.33333 h=54
        R v==eq($og1_sel,0) x=23 y=139 w=139.33333 h=56 rx=5 f=none s=#3D8BFD sw=2
        R x=24.5 y=140.5 w=136.33333 h=53 rx=3.5 f=#2C2C2C s=#4A4A4A sw=1 fo==1-0.25*down
    }
    G id=og1_g1 {
        R id=og1_o1 click=1 x=171.33333 y=140 w=137.33333 h=54
        R v==eq($og1_sel,1) x=170.33333 y=139 w=139.33333 h=56 rx=5 f=none s=#3D8BFD sw=2
        R x=171.83333 y=140.5 w=136.33333 h=53 rx=3.5 f=#2C2C2C s=#4A4A4A sw=1 fo==1-0.25*down
    }
    G id=og1_g2 {
        R id=og1_o2 click=1 x=318.66666 y=140 w=137.33333 h=54
        R v==eq($og1_sel,2) x=317.66666 y=139 w=139.33333 h=56 rx=5 f=none s=#3D8BFD sw=2
        R x=319.16666 y=140.5 w=136.33333 h=53 rx=3.5 f=#2C2C2C s=#4A4A4A sw=1 fo==1-0.25*down
    }
    T x=24 y=140 w=137.33333 h=54 text=Auto size=22 weight=bold f=#F2F2F2 align=center valign=middle fit=ellipsis
    T x=171.33333 y=140 w=137.33333 h=54 text=On size=22 weight=bold f=#F2F2F2 align=center valign=middle fit=ellipsis
    T x=318.66666 y=140 w=137.33333 h=54 text=Off size=22 weight=bold f=#F2F2F2 align=center valign=middle fit=ellipsis
}
# widget eventlog log1 {"x":24,"y":250,"w":432,"h":100,"rows":2,"time":false,"pitch":56,"keys":{}}
G id=log1 {
    R x=24 y=250 w=432 h=100
    RP n=2 {
        G v==gt($log1_k[i],0) {
            R x=24 y==250+i*56 w=432 h=44 rx=4 f=#2C2C2C
            R x=38 y==250+i*56+8 w=72 h=28 rx=3 f==if(eq($log1_k[i],1),#4CC38A,if(eq($log1_k[i],2),#F0B429,if(eq($log1_k[i],3),#EF5350,#9A9A9A)))
            T v==eq($log1_k[i],1) x=38 y==250+i*56+8 w=72 h=28 text=OK size=20 weight=bold f=#111111 align=center valign=middle
            T v==eq($log1_k[i],2) x=38 y==250+i*56+8 w=72 h=28 text=WARN size=20 weight=bold f=#111111 align=center valign=middle
            T v==eq($log1_k[i],3) x=38 y==250+i*56+8 w=72 h=28 text=CRIT size=20 weight=bold f=#111111 align=center valign=middle
            T x=124 y==250+i*56 w=318 h=44 text="$log1_m[i]" size=22 f=#F2F2F2 valign=middle fit=ellipsis missing=""
        }
    }
}
# widget button btn1 {"x":24,"y":400,"w":200,"h":54,"states":[{"label":"Devices","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=btn1 {
    R id=btn1_hit click=1 x=24 y=400 w=200 h=54
    R x=24.5 y=400.5 w=199 h=53 rx=3.5 f=#2C2C2C s=#4A4A4A sw=1 fo==1-0.25*down
    T x=42 y=400 w=164 h=54 text=Devices size=22 weight=bold f=#F2F2F2 align=center valign=middle fit=ellipsis
}
G v==lt(ver,11118) {
    R x=0 y=0 w=480 h=58 f=#000000CC
    T x=14.4 y=0 w=451.2 h=58 text="Update ScriptedScreens Vector to 0.11.118 or newer" size=26 f=#FFCC00
}

SCENE w=480 h=480 fit=contain
# widget header vbhdr {"x":24,"y":24,"w":432,"h":56,"title":"Devices","clock":false,"counts":false,"keys":{}}
G id=vbhdr {
    R x=24.5 y=24.5 w=431 h=55 f=#1A1A1A s=#4A4A4A sw=1
    T x=42 y=28 w=386 h=48 text=Devices size=30 weight=bold f=#F2F2F2 valign=middle fit=ellipsis
}
# widget repeater vbdev {"x":24,"y":90,"w":432,"h":206,"max":4,"layout":"list","cols":2,"pitch":54,"item":"row","fmt":"","click":true,"keys":{}}
G id=vbdev {
    R x=24 y=90 w=432 h=206
    RP n=4 {
        G v==lt(i,$vbdev_n) {
            R id=vbdev_r click=1 x=24 y==90+i*54 w=432 h=44
            R x=24 y==90+i*54 w=432 h=44 rx=4 f=#2C2C2C
            C v==1-eq($vbdev_st[i],1)-eq($vbdev_st[i],2)-eq($vbdev_st[i],3) cx=46 cy==90+i*54+22 rx=8 ry=8 f=#9A9A9A
            C v==eq($vbdev_st[i],1) cx=46 cy==90+i*54+22 rx=8 ry=8 f=#4CC38A
            C v==eq($vbdev_st[i],2) cx=46 cy==90+i*54+22 rx=8 ry=8 f=#F0B429
            C v==eq($vbdev_st[i],3) cx=46 cy==90+i*54+22 rx=8 ry=8 f=#EF5350
            T x=64 y==90+i*54 w==lerp(258,378,clamp(and($vbdev_ready,eq($vbdev_hasv[i],0)),0,1)) h=44 text="$vbdev_name[i]" size=24 f=#F2F2F2 valign=middle fit=ellipsis missing=""
            T v==not(and($vbdev_ready,eq($vbdev_hasv[i],0))) x=332 y==90+i*54 w=110 h=44 text="{$vbdev_v[i]:%.1f}" size=28 f=#F2F2F2 align=right valign=middle
        }
    }
}
# widget text vbmsg {"x":24,"y":306,"w":432,"h":34,"style":"value","text":"$vbdev_msg","align":"left","state":false,"keys":{}}
G id=vbmsg {
    T x=24 y=306 w=432 h=34 text=$vbdev_msg size=24 f=#F2F2F2 valign=middle fit=ellipsis
}
# widget text vbpg {"x":171.33333,"y":357,"w":137.33333,"h":34,"style":"value","text":"$vbdev_pg","align":"center","state":false,"keys":{}}
G id=vbpg {
    T x=171.33333 y=357 w=137.33333 h=34 text=$vbdev_pg size=24 f=#F2F2F2 align=center valign=middle fit=ellipsis
}
# widget button vbprev {"x":24,"y":350,"w":137.33333,"h":48,"states":[{"label":"PREV","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=vbprev {
    R id=vbprev_hit click=1 x=24 y=350 w=137.33333 h=48
    R x=24.5 y=350.5 w=136.33333 h=47 rx=3.5 f=#2C2C2C s=#4A4A4A sw=1 fo==1-0.25*down
    T x=42 y=350 w=101.33333 h=48 text=PREV size=22 weight=bold f=#F2F2F2 align=center valign=middle fit=ellipsis
}
# widget button vbnext {"x":318.66666,"y":350,"w":137.33333,"h":48,"states":[{"label":"NEXT","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=vbnext {
